function UIEntrustTasksDialog:Awake()
    local argument = self.controller.Argument.parameters
    buyHpLimit = checkInt(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 16).num)
    if isNull(argument.type) then
        if not isNull(argument.levelId) then ----默认选完关卡和难度,不可再进行选择
            self._curLevelId = checkNumber(argument.levelId)
            self._curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)   --关卡配置
            if not self._curLevelVo then
                return
            end
            self.openType = OpenType.Level
            self.isOpenFromHome = false
        end
    elseif argument.type == OpenType.Home then
        self.openType = OpenType.Home
        self.isOpenFromHome = true
    end
    self._allCountDownTimer = {}
    local StoreConstants = import('Game.UI.Store.StoreConstants')
    -- 海外月卡没有特权修改
    --local monthCardNum = checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.AutoTimes))
    local monthCardNum = 0
    if monthCardNum ~= 0 then--可以取到时间说明购买了月卡
        self.isBuyMonthCard = true
    end
    self:InitData(function ()
        self.EventEntrustDataRefesh = Events.AddListener(Constants.EventNames.EntrustDataRefesh, Bind(self, self.OnEntrustDataRefesh))
        self.EventUIEntrustBattleSuccess = Events.AddListener(Constants.EventNames.UIEntrustBattleSuccess, Bind(self, self.OnUIEntrustBattleSuccess))

        self:FillSelf()
    end)

end

function UIEntrustTasksDialog:FillSelf()
    --KTool.SetActive(self.StateMonthCard, true)
    --local posY = self.isBuyMonthCard and -1135 or -1080
    --self.CommonHangUpTeams.anchoredPosition = Vector2.New(self.CommonHangUpTeams.anchoredPosition.x, posY)
    self.ImgIcon.Status = self.isBuyMonthCard and 2 or 1
    local UIEntrusts = CfUtils.GetLuaScr(self.UIEntrusts, "Game.UI.FightTeam.Entrust.UIEntrusts")
    if UIEntrusts then
        UIEntrusts:RefeshSelf(1, self._curLevelId, function(entrustId)
            if not isNull(UIEntrusts.rewardGetQueueId) then
                if UIEntrusts.rewardGetQueueId ~= -1 then
                    self.isGetReward = true
                end
            end
            --KCookie.Set(FirstSelectLuaIndex, nil)
            self:OnSelectEntrust(entrustId)
        end, self.isOpenFromHome)
    end
end

--绘制选择关卡时候  选择一个队列
function UIEntrustTasksDialog:OnSelectEntrust(entrustId)
    local dojo = teamComponent:GetEntrustQueueData(entrustId)
    if not dojo then
        return
    end
    self.isOpenDifficultySelect = false
    self._entrustNum = 1                 --委托次数重置
    if self.isGetReward then
        self.isGetReward = false
        self:FillRightInfo()
        KCookie.Set(FirstSelectLuaIndex, nil)
        KCookie.Set(SecondSelectLuaIndex, nil)
    else
        if self._curEntrustId ~= checkString(entrustId) then--屏蔽重复选择 领取奖励后除外
            self._curEntrustId = checkString(entrustId)
            if self.isOnOpen then--第一次打开界面时不清，后面每次点击选择时清
                self.isOnOpen = false
            else
                KCookie.Set(FirstSelectLuaIndex, nil)
                KCookie.Set(SecondSelectLuaIndex, nil)
            end
            self:FillRightInfo()
        end
    end
end

--绘制右边委托信息
function UIEntrustTasksDialog:FillRightInfo()
    self:ClearTimeDown()
    local isLevelEntrusting
    local firstSelectLuaIndex = KCookie.Get(FirstSelectLuaIndex)
    if self.isOpenFromHome then--从主页进入
        self._curLevelId = nil
        local dojo = teamComponent:GetEntrustQueueData(self._curEntrustId)
        if not dojo then
            return
        end
        isLevelEntrusting = checkNumber(dojo.questId) ~= 0
        if isLevelEntrusting then
            self:FillEntrustIng()
            self:ShowTargetRightPanel(TargetRightPanel.OverOrGoing)
        else
            if not isNull(firstSelectLuaIndex) then
                self.firstSelectLuaIndex = firstSelectLuaIndex
                self.secondSelectLuaIndex = KCookie.Get(SecondSelectLuaIndex)
                self:FillSecondSelectQuest()
                self:ShowTargetRightPanel(TargetRightPanel.Second)
            else
                self:FillFirstSelectQuest()
                self:ShowTargetRightPanel(TargetRightPanel.First)
            end
        end
    else
        isLevelEntrusting = (teamComponent:GetEntrustQueueDataByQuestId(self._curLevelId) and true or false)
        if isLevelEntrusting then--委托中
            self:FillEntrustIng()
            self:ShowTargetRightPanel(TargetRightPanel.OverOrGoing)
        else
            self:FillSecondSelectQuest()
            self:ShowTargetRightPanel(TargetRightPanel.Second)
        end
    end
end

---
function UIEntrustTasksDialog:ShowTargetRightPanel(type)
    KTool.SetActive(self.Group3, type == TargetRightPanel.First)
    KTool.SetActive(self.Group2, type == TargetRightPanel.Second)
    KTool.SetActive(self.Group1, type == TargetRightPanel.OverOrGoing)
end

--group1 委托中
function UIEntrustTasksDialog:FillEntrustIng()
    local dojo = teamComponent:GetEntrustQueueData(self._curEntrustId)
    if not dojo then
        return
    end
    local firstLuaIndex
    local secondLuaIndex
    for k, v in ipairs(self.data) do
        for i, b in ipairs(v.ids) do
            if checkNumber(b) == checkNumber(dojo.questId) then
                firstLuaIndex = k
                secondLuaIndex = i
                self.firstSelectLuaIndex = k
                self.secondSelectLuaIndex = i
            end
        end
    end
    self._curLevelId = dojo.questId
    CfUtils.FillText(self.TxtTitle1, self.data[firstLuaIndex].name)
    CfUtils.FillText(self.TxtEntrustingDifficulty, secondLuaIndex)
    KTool.SetActive(self.ButtonGroup, true)
    KTool.SetActive(self.FontStyleButton, true)
    KTool.SetActive(self.Began, false)
    local isEnd = teamComponent:IsEntrustingEnd(self._curEntrustId)
    KTool.SetActive(self.State2, isEnd)
    KTool.SetActive(self.State1, not isEnd)
    --如果结束了
    if isEnd then
        self:FillGroupEndStatus()
        self:FillRewards(rewardType.Get)
    else
        self:FillGroupEnturstingStatus()
    end

end

--绘制委托结束信息
function UIEntrustTasksDialog:FillGroupEndStatus()
    self:ClearTimeDown()
    local dojo = teamComponent:GetEntrustQueueData(self._curEntrustId)
    CfUtils.FillText(self.TxtTimeDown, 0)
    CfUtils.FillText(self.CurTime, teamComponent:GetAllEntrustTime(self._curEntrustId).."/"..dojo.questSum)
    self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B1", localize("领取奖励"))
    SetButtonAction(self.FontStyleButton, function()
        KCookie.Set(FirstSelectLuaIndex, self.firstSelectLuaIndex)
        KCookie.Set(SecondSelectLuaIndex, self.secondSelectLuaIndex)
        teamComponent:EntrustGetRewardReq(self._curEntrustId)
    end)
end

--绘制委托进行中信息
function UIEntrustTasksDialog:FillGroupEnturstingStatus()
    local dojo = teamComponent:GetEntrustQueueData(self._curEntrustId)
    local isHaveTask = teamComponent:IsEntrustQueuesBusy(self._curEntrustId)
    if isHaveTask then
        self:FillRewards(rewardType.Get)
        self:ClearTimeDown()
        local _timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
            local time = teamComponent:GetEntrustRemainTime(self._curEntrustId)
            if time > 0 then
                CfUtils.FillText(self.TxtTimeDown, CfUtils.GetTimeHMS(time))
                CfUtils.FillText(self.CurTime, teamComponent:GetAllEntrustTime(self._curEntrustId).."/"..dojo.questSum)
            else
                CfUtils.FillText(self.TxtTimeDown, 0)
                CfUtils.FillText(self.CurTime, dojo.questSum.."/"..dojo.questSum)
                self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B1", localize("领取奖励"))
                --领取奖励
                SetButtonAction(self.FontStyleButton, function()
                    KCookie.Set(FirstSelectLuaIndex, self.firstSelectLuaIndex)
                    KCookie.Set(SecondSelectLuaIndex, self.secondSelectLuaIndex)
                    teamComponent:EntrustGetRewardReq(self._curEntrustId)
                end)
                KTool.SetActive(self.State2, true)
                KTool.SetActive(self.State1, false)
            end
        end, 604800, true, true, true)
        table.insert(self._allCountDownTimer, _timer)
        self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B5", localize("取消委托"))
        --取消委托
        SetButtonAction(self.FontStyleButton, function()
            GameUtils.SecondConfirm(localize("是否确定取消任务？"), function()
                teamComponent:EntrustGetRewardReq(dojo.id)
                local UIEntrusts = CfUtils.GetLuaScr(self.UIEntrusts, "Game.UI.FightTeam.Entrust.UIEntrusts")
                if UIEntrusts then
                    UIEntrusts.rewardGetQueueId = nil
                end
            end, nil, localize("取消委任不会返还扣除的体力(已完成_num_场)", {_num_ = teamComponent:GetAllEntrustTime(self._curEntrustId)}))
        end)
    end

end

---group3 一级选择，选择关卡
function UIEntrustTasksDialog:FillFirstSelectQuest()
    KTool.SetActive(self.Began, false)
    KTool.SetActive(self.FontStyleButton, false)
    if not self.FirstSelectLoopList.IsListViewInit then
        self.FirstSelectLoopList:InitGridView(#self.data, Bind(self, self.OnGetItemByIndexFirst))
        self.firstViewPortWidth = self.FirstSelectLoopList.ViewPortWidth
    else
        GameUtils.ReloadData(self.FirstSelectLoopList, #self.data)
    end
    self.FirstSelectLoopListContent:SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, self.FirstSelectLoopList.ViewPortWidth)
end

---一级选择关卡的循环列表
function UIEntrustTasksDialog:OnGetItemByIndexFirst(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local node = GetLuaBehaviour(cell.gameObject, "Game.UI.FightTeam.Entrust.UIEntrustTasksFirstSelectNode")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        local luaIndex = index + 1
        CfUtils.AdaptiveParentWidth(node, self.firstViewPortWidth)
        --local rt = node.gameObject:GetComponent(typeof(RectTransform))
        --rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, self.FirstSelectLoopList.ViewPortWidth)
        node.Env:FreshBaseUI(self.data[luaIndex])
        ---不能选置灰
        local canEntrust = self:CanEntrust(luaIndex)
        local isAllEntrusting = isNull(self:GetMaxDifficultyLuaIndex(luaIndex))
        node.Env:FreshActiveStatus(canEntrust and (not isAllEntrusting))
        node.Env:SetCallBack(function() --点击回调
            if canEntrust then
                local isAllEntrusting = isNull(self:GetMaxDifficultyLuaIndex(luaIndex))
                if isAllEntrusting then
                    GameUtils.Toast(localize("该类型暂无可进行委任的关卡"))
                else
                    KTool.SetActive(self.Group3, false)
                    KTool.SetActive(self.Group2, true)
                    self.firstSelectLuaIndex = luaIndex
                    if self.isOpenFromHome then
                        self._curLevelId = nil
                        self.secondSelectLuaIndex = nil
                    end
                    KCookie.Set(FirstSelectLuaIndex, self.firstSelectLuaIndex)
                    KCookie.Set(SecondSelectLuaIndex, self.secondSelectLuaIndex)
                    self.isSelectFirst = true
                    self:FillSecondSelectQuest()
                end
            else
                GameUtils.Toast(localize("该类型关卡均未达成三星条件，无法进行委任战斗"))
            end
        end)
    end
    return cell
end

---当前类型的关卡可以委托
function UIEntrustTasksDialog:CanEntrust(luaIndex)
    local canEntrust = false
    for k, v in ipairs(self.data[luaIndex].ids) do
        local isUnlock = QuestConfMgr:GetInstance():IsUnlockEntrust(v)
        if isUnlock then
            canEntrust = true
            return canEntrust
        end
    end
    return canEntrust
end

---group2 二级选择 该关卡没有委托
function UIEntrustTasksDialog:FillSecondSelectQuest()
    if not isNull(self._curLevelId) then
        for k, v in ipairs(self.data) do
            for i, b in ipairs(v.ids) do
                if checkNumber(b) == checkNumber(self._curLevelId) then
                    self.firstSelectLuaIndex = k
                    self.secondSelectLuaIndex = i
                end
            end
        end
    else
        if isNull(self.secondSelectLuaIndex) then
            self.secondSelectLuaIndex = self:GetMaxDifficultyLuaIndex(self.firstSelectLuaIndex)
            if isNull(self.secondSelectLuaIndex) then
                return
            end
        end

    end
    CfUtils.FillText(self.TxtSecondSelectLevelName, self.data[self.firstSelectLuaIndex].name)
    KTool.SetActive(self.ButtonGroup, true)
    KTool.SetActive(self.BtnSecondSelectClose, self.isOpenFromHome)
    --是否自动使用猫眼石兑换体力
    KTool.SetActive(self.ImgOk, self.isAutoUse)
    SetButtonAction(self.Btnselect, function ()
        self.isAutoUse = not self.isAutoUse
        KTool.SetActive(self.ImgOk, self.isAutoUse)
        self:FillEntrustUseItems()
    end)
    --
    SetButtonAction(self.BtnSecondSelectClose, function() --返回一级选择
        if self.isOpenFromHome then
            self:FillFirstSelectQuest()
            self.secondSelectLuaIndex = nil
            self._curLevelId = nil
            self.isOpenDifficultySelect = false
            KTool.SetActive(self.ButtonGroup, false)
            KTool.SetActive(self.Group2, false)
            KTool.SetActive(self.Group3, true)
        end
    end)
    self._curLevelId = self.data[self.firstSelectLuaIndex]["ids"][self.secondSelectLuaIndex]
    self._curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)
    SetButtonAction(self.BtnSecondSelectDifficulty, function() --打开难度选择
        if self.isOpenFromHome then
            self.isOpenDifficultySelect = not self.isOpenDifficultySelect
            self:ChangeSelectDifficultyStatus()
        end
    end)
    self:ChangeSelectDifficultyStatus()
    --委托条件
    self:FillEntrustConditions()
    --委托奖励
    self:FillRewards(rewardType.Set)
    --减少委托次数
    SetButtonAction(self.Btnsubtract, function()
        if checkNumber(self._entrustNum) > 1 then
            self._entrustNum = self._entrustNum - 1
            self:FillEntrustNum()
            self:FillEntrustTime()
            self:FillEntrustUseItems()
            teamComponent:SetEntrustNum(self._entrustNum)
        end
    end)

    --增加委托次数
    SetButtonAction(self.Btnadd, function()
        if self._entrustNum < self._maxEntrustNum then
            self._entrustNum = self._entrustNum + 1
            self:FillEntrustNum()
            self:FillEntrustTime()
            self:FillEntrustUseItems()
            teamComponent:SetEntrustNum(self._entrustNum)
        else
            GameUtils.Toast(localize("已达到委托最大次数！"))
        end
    end)
    self.TxtNumEntrust.onEndEdit:AddListener(function()
        self.TxtNumEntrust.text = Mathf.Clamp(checkNumber(self.TxtNumEntrust.text), 1, self._maxEntrustNum)
        self._entrustNum = checkNumber(self.TxtNumEntrust.text)
        self:FillEntrustTime()
        self:FillEntrustUseItems()
        teamComponent:SetEntrustNum(self._entrustNum)
    end)

    self:FillEntrustNum()
    self:FillEntrustTime()
    self:FillEntrustUseItems()
    --
    KTool.SetActive(self.FontStyleButton, true)
    KTool.SetActive(self.Began, true)
    self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle(self._isCanEntrust and "B1" or "B5", localize("开始委托"))
    ----开始委托
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local remainNum = buyHpLimit - checkNumber(playerComponent.playerDojo.buyHpNum)
    local text = string.format("今日剩余情绪兑换次数%s/%s", math.tointeger(remainNum), buyHpLimit)
    SetButtonAction(self.FontStyleButton, function()
        if self._isCanEntrust then
            local unusedGoods = self.isAutoUse and {} or {checkString(Constants.Currency.FreeDiamondId)}
            local useItems = CfUtils.GetUseItemByStrenth((self._curLevelVo.costNum + self._curLevelVo.costNumLose) * self._entrustNum, true, unusedGoods)
            --printInfo("===>>"..table.dump(useItems))
            if useItems[1].isEnough then
                GameUtils.SecondConfirm(localize("是否消耗材料开始委托任务？"), function()
                    for k, v in pairs(useItems) do
                        if checkNumber(v.goodsId) == Constants.Currency.FreeDiamondId then--购买次数限制
                            local changeData = CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", Constants.Currency.FreeDiamondId)
                            local number = v.num / checkNumber(changeData.itemIdCost)--兑换次数
                            --local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                            local buyHpLimit = checkInt(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 16).num)
                            local remainNum = buyHpLimit - checkNumber(playerComponent.playerDojo.buyHpNum) - number
                            if remainNum < 0 then
                                GameUtils.Toast(localize("今日剩余体力兑换次数不足"))
                                return
                            end
                        end
                    end
                    teamComponent:EntrustReq(self._curLevelId, self._entrustNum, self._curLevelVo, self._curEntrustId, unusedGoods)
                    local UIEntrusts = CfUtils.GetLuaScr(self.UIEntrusts, "Game.UI.FightTeam.Entrust.UIEntrusts")
                    if UIEntrusts then
                        UIEntrusts.rewardGetQueueId = nil
                    end
                end, nil, text, 4, useItems)
            else
                UIModule.OpenDialog({ id = Constants.UITypeIds.UIHPDialog, parameters = { strengthChangeCB = function() self:FillEntrustUseItems() end } })
            end
        else
            GameUtils.Toast(localize("委托作战条件未达成"))
        end
    end)
end

---获取类型关卡可进行委任战斗的最高难度的luaIndex 从1开始
function UIEntrustTasksDialog:GetMaxDifficultyLuaIndex(luaIndex)
    for i = #self.data[luaIndex].ids, 1, -1 do --倒序
        local isUnlock = QuestConfMgr:GetInstance():IsUnlockEntrust(self.data[luaIndex]["ids"][i])
        if isUnlock then
            local isLevelEntrusting = (teamComponent:GetEntrustQueueDataByQuestId(self.data[luaIndex]["ids"][i]) and true or false)
            if not isLevelEntrusting then
                return i
            end
        end
    end
    return nil
end

--绘制委托次数按钮
function UIEntrustTasksDialog:FillEntrustNum()
    self.TxtNumEntrust.text = self._entrustNum
    --CfUtils.FillText(self.TxtNumEntrust, self._entrustNum)
    CfUtils.FillText(self.TxtNum, (self._curLevelVo.costNum + self._curLevelVo.costNumLose) * self._entrustNum)
end

--绘制委托所需时间
function UIEntrustTasksDialog:FillEntrustTime()
    local StoreConstants = import('Game.UI.Store.StoreConstants')
    --local monthCardNum = checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.AutoTimes))
    --if monthCardNum == 0 then
    --    monthCardNum = 1
    --end
    local monthCardNum = 1
    local allNeedTime = checkNumber(self._entrustNum * checkNumber(self._curLevelVo.time * monthCardNum))
    local txt
    if self.isBuyMonthCard then
        --txt = string.format("%s<color=#7be134>(-%s\\%)</color>", CfUtils.GetTimeHMS(allNeedTime), monthCardNum * 100)
        txt = string.format("%s<color=#7be134>(-%s</color>", CfUtils.GetTimeHMS(allNeedTime), monthCardNum * 100).."<color=#7be134>%)</color>"
    else
        txt = CfUtils.GetTimeHMS(allNeedTime)
    end
    CfUtils.FillCfText(self.TxtRequireTime, txt)
end

--绘制委托所需材料
function UIEntrustTasksDialog:FillEntrustUseItems()
    local unusedGoods = self.isAutoUse and {} or {checkString(Constants.Currency.FreeDiamondId)}
    local useItems = CfUtils.GetUseItemByStrenth((self._curLevelVo.costNum + self._curLevelVo.costNumLose) * self._entrustNum, true, unusedGoods)
    for i = 1, #useItems do
        local go = self.consumes.transform:Find("consume"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.consume, self.consumes)
            go.name = "consume"..i
        end
        self:FillEntrustUseItem(go, useItems[i])
    end

    if #useItems < self.consumes.transform.childCount then
        for i = #useItems + 1, self.consumes.transform.childCount - 1 do
            local go = self.consumes.transform:Find("consume"..i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.consumes)
end

--绘制委托所需材料
function UIEntrustTasksDialog:FillEntrustUseItem(go, item)
    if not go or not item then return end
    --小于0的时候不绘制
    if checkNumber(item.num) <= 0 and item.goodsId ~= Constants.Currency.HpId then
        KTool.SetActive(go, false)
        return
    end
    local col = item.isEnough and "#cccccc" or "#ff0000"
    CfUtils.FillText(go, string.format_color_tag(checkNumber(item.num), col))

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(item.goodsId)
    if vo then
        CfUtils.FillImage(go.transform:Find("icon"), vo.photoPath)
    end
    KTool.SetActive(go, true)
end

--绘制委托条件
function UIEntrustTasksDialog:FillEntrustConditions()
    local teamTab = teamComponent:GetEntrustTeamData(self._curEntrustId)
    local powerNum = teamComponent:GetTeamFightingPower(teamTab)
    --条件一和条件二
    for i = 1, 2 do
        local desc
        if i == 1 then
            desc = localize("队伍武装值达到")
            CfUtils.FillText(self["TxtSecondSelectCondition"..i], desc..self._curLevelVo.teamLimit)
            if self._curLevelVo.teamLimit <= powerNum then
                CfUtils.FillImage(self["ImgSecondSelectCondition"..i], "UIAtlas/FightTeam/EntrustTeam/auto_bg_text_get")
                CfUtils.SetColor(self["TxtSecondSelectCondition"..i], XLuaUtils.HexToColor("e9e9e9"))
                CfUtils.SetColor(self["ImgPointSecondSelectCondition"..i], XLuaUtils.HexToColor("e9e9e9"))
                KTool.SetActive(self["ImgOkSecondSelectCondition"..i], true)
                self._isCanEntrust = true
            else
                CfUtils.FillImage(self["ImgSecondSelectCondition"..i], "UIAtlas/FightTeam/EntrustTeam/auto_bg_text_noget")
                CfUtils.SetColor(self["TxtSecondSelectCondition"..i], XLuaUtils.HexToColor("6d6d6d"))
                CfUtils.SetColor(self["ImgPointSecondSelectCondition"..i], XLuaUtils.HexToColor("6d6d6d"))
                KTool.SetActive(self["ImgOkSecondSelectCondition"..i], false)
                self._isCanEntrust = false
            end
        elseif i == 2 then
            desc = localize("队伍武装数量达到")
            local maxCount = QuestConfMgr:GetInstance():GetTeamMemberNum(self._curLevelId)
            CfUtils.FillText(self["TxtSecondSelectCondition"..i], desc..maxCount)
            if teamComponent:GetTeamMemberCount(teamTab) >= maxCount then
                CfUtils.FillImage(self["ImgSecondSelectCondition"..i], "UIAtlas/FightTeam/EntrustTeam/auto_bg_text_get")
                CfUtils.SetColor(self["TxtSecondSelectCondition"..i], XLuaUtils.HexToColor("e9e9e9"))
                CfUtils.SetColor(self["ImgPointSecondSelectCondition"..i], XLuaUtils.HexToColor("e9e9e9"))
                KTool.SetActive(self["ImgOkSecondSelectCondition"..i], true)
                --if self._isCanEntrust then
                --    self._isCanEntrust = true
                --else
                --
                --end

            else
                CfUtils.FillImage(self["ImgSecondSelectCondition"..i], "UIAtlas/FightTeam/EntrustTeam/auto_bg_text_noget")
                CfUtils.SetColor(self["TxtSecondSelectCondition"..i], XLuaUtils.HexToColor("6d6d6d"))
                CfUtils.SetColor(self["ImgPointSecondSelectCondition"..i], XLuaUtils.HexToColor("6d6d6d"))
                KTool.SetActive(self["ImgOkSecondSelectCondition"..i], false)
                self._isCanEntrust = false
            end
        end
    end
end

function UIEntrustTasksDialog:FillRewards(type)
    --奖励
    local rewardData = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curLevelId)
    if not rewardData then
        return
    end
    local t = {}
    local count = 1
    for i = 1, table.count(rewardData) do
        if count < 4 then
            local data = rewardData[i]
            if data.type == Constants.TeamShowRewardType.StarType then
                --领取过的不显示
                if not QuestConfMgr:GetInstance():IsPassAndCompleteAllCdtQuest(self._curLevelId) then
                    table.insert(t, rewardData[i])
                    count = count + 1
                end
            elseif data.type == Constants.TeamShowRewardType.FristType then
                --领取过的不显示
                if not QuestConfMgr:GetInstance():IsPassQuest(self._curLevelId) then
                    table.insert(t, rewardData[i])
                    count = count + 1
                end
            else
                table.insert(t, rewardData[i])
                count = count + 1
            end
        end
    end
    local node
    if type == rewardType.Set then
        node = self.SecondSelectRewardsNode
    elseif type == rewardType.Get then
        node = self.EntrustingRewardsNode
    end
    local scr = CfUtils.GetLuaScr(node, UIFightReardsNode)
    if scr then
        scr:Refersh(t, 0.65, true)
        scr:RefershSpacing(-57)
    end
end

---改变选择难度的箭头和循环列表
function UIEntrustTasksDialog:ChangeSelectDifficultyStatus()
    CfUtils.FillText(self.TxtSecondSelectDifficulty, self.secondSelectLuaIndex)
    KTool.SetActive(self.ImgInform1DropDown, self.isOpenDifficultySelect)
    self.ImgArrowSecondSelectDifficulty.localEulerAngles = Vector3.New(0, 0, self.isOpenDifficultySelect and 180 or 0)
    CfUtils.SetUISwitchImage(self.BtnSecondSelectDifficulty, self.isOpenFromHome and 2 or 1)
    if self.isOpenDifficultySelect then
        if not self.SecondSelectLoopList.IsListViewInit then
            self.SecondSelectLoopList:InitGridView(#self.data[self.firstSelectLuaIndex].ids, Bind(self, self.OnGetItemByIndexSecond))
            self.secondViewPortWidth = self.SecondSelectLoopList.ViewPortWidth
        else
            GameUtils.ReloadData(self.SecondSelectLoopList, #self.data[self.firstSelectLuaIndex].ids)
        end
        self.SecondSelectLoopListContent:SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, self.SecondSelectLoopList.ViewPortWidth)
    end
end

---二级选择关卡的循环列表
function UIEntrustTasksDialog:OnGetItemByIndexSecond(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local node = GetLuaBehaviour(cell.gameObject, "Game.UI.FightTeam.Entrust.UIEntrustTasksSecondSelectNode")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        --local rt = node.gameObject:GetComponent(typeof(RectTransform))
        CfUtils.AdaptiveParentWidth(node, self.secondViewPortWidth)
        --if not isNull(self.FirstSelectLoopList.ViewPortWidth) then
        --    printInfo("ViewPortWidth=======>>"..self.FirstSelectLoopList.ViewPortWidth)
        --    rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, self.FirstSelectLoopList.ViewPortWidth)
        --end
        local luaIndex = index + 1
        local levelId = self.data[self.firstSelectLuaIndex]["ids"][luaIndex]
        node.Env:FreshBaseUI({
            id = levelId
        })
        node.Env:SetCallBack(function() --点击回调
            local isLevelEntrusting = (teamComponent:GetEntrustQueueDataByQuestId(levelId) and true or false)
            local isUnlock = QuestConfMgr:GetInstance():IsUnlockEntrust(levelId)
            if isUnlock and (not isLevelEntrusting) then --解锁了并且不在委托中
                self.secondSelectLuaIndex = luaIndex
                self._curLevelId = self.data[self.firstSelectLuaIndex]["ids"][self.secondSelectLuaIndex]
                self.isOpenDifficultySelect = false
                self:ChangeSelectDifficultyStatus()
                self:FillSecondSelectQuest()
            end
        end)
    end
    return cell
end

--委托数据刷新界面
function UIEntrustTasksDialog:OnEntrustDataRefesh(body)
    local dojo = teamComponent:GetEntrustQueueData(self._curEntrustId)
    if not dojo then
        return
    end
    
    self:ClearTimeDown()
    self:FillRightInfo()
end

--委托成功后回调刷新界面
function UIEntrustTasksDialog:OnUIEntrustBattleSuccess(body)
    self:ClearTimeDown()
    self:FillRightInfo()
end

function UIEntrustTasksDialog:ClearTimeDown()
    if not isNull(self._allCountDownTimer) then
        ---删除计时器
        for i, v in pairs(self._allCountDownTimer) do
            CDTimerModule.GetInstance():RemoveCD(v)
        end
        self._allCountDownTimer = {}
    end
end

