function UIEntrustTasksDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UIEntrustTasksDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            Events.RemoveListener(Constants.EventNames.EntrustDataRefesh, self.EventEntrustDataRefesh)
            Events.RemoveListener(Constants.EventNames.UIEntrustBattleSuccess, self.EventUIEntrustBattleSuccess)
            self:ClearTimeDown()
        end
        if isNull(self.isSelectFirst) then
            KCookie.Set(FirstSelectLuaIndex, nil)
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIEntrustTasksDialog
